"""Writes firmware/lib/ad_templates.h (spell templates) and firmware/test/vectors.h (synthetic traces + the Python reference verdict) from gesture_sim.py."""
import os, numpy as np
import gesture_sim as G
HERE = os.path.dirname(os.path.abspath(__file__)); LIB = os.path.join(HERE, "..", "firmware", "lib"); TST = os.path.join(HERE, "..", "firmware", "test")
t = ["/* generated by sim/gen_headers.py: normalised 16-point spell templates (x right, y up) */", "#define AD_NT 6", "#ifdef __AVR__", "#include <avr/pgmspace.h>", "#define AD_ROM PROGMEM", "#define AD_RF(p) pgm_read_float(&(p))", "#define AD_RW(p) pgm_read_word(&(p))", "#else", "#define AD_ROM", "#define AD_RF(p) (p)", "#define AD_RW(p) (p)", "#endif", "static const float AD_TEMPL[AD_NT][16][2] AD_ROM = {"]
for n in G.NAMES: t.append("  { " + ", ".join(f"{{{p[0]:.5f}f,{p[1]:.5f}f}}" for p in G.TEMPL[n]) + " },  /* " + n + " */")
t += ["};", f"#define AD_D_MAX {G.D_MAX}f", f"#define AD_MARGIN {G.MARGIN}f", f"#define AD_MIN_EXTENT {G.MIN_EXTENT_DEG}f"]
open(os.path.join(LIB, "ad_templates.h"), "w").write("\n".join(t) + "\n")
rng = np.random.default_rng(2024); rows = []; v = ["/* generated by sim/gen_headers.py: synthetic traces and the reference (Python) verdict: -1 = fizzle, 0..5 = spell */", "typedef struct { int n; int expect_py; int truth; const int16_t *g; const int16_t *a; const uint8_t *trig; } ad_vec_t;"]
k = 0; entries = []
def add(tr, truth):
    global k
    g, a, trig = tr; res = G.recognise(g, a, trig)[0]; exp = G.NAMES.index(res) if res else -1
    v.append(f"static const int16_t vg{k}[] = {{" + ",".join(str(int(x)) for x in g.flatten()) + "};")
    v.append(f"static const int16_t va{k}[] = {{" + ",".join(str(int(x)) for x in a.flatten()) + "};")
    v.append(f"static const uint8_t vt{k}[] = {{" + ",".join("1" if x else "0" for x in trig) + "};")
    entries.append(f"  {{{len(g)}, {exp}, {truth}, vg{k}, va{k}, vt{k}}},"); k += 1
for i, nm in enumerate(G.NAMES):
    for _ in range(6): add(G.synth(nm, rng, 1.2), i)
for _ in range(6): add(G.synth(G.scribble(rng), rng, 1.2, raw=True), -1)
for _ in range(4): add(G.synth(G.poly([(0, 0), (rng.uniform(-1, 1), rng.uniform(-1, 1))], 10) * 3.0, rng, 1.2, raw=True), -1)
v += ["static const ad_vec_t AD_VECS[] = {"] + entries + ["};", f"#define AD_NVEC {k}"]
open(os.path.join(TST, "vectors.h"), "w").write("\n".join(v) + "\n"); print("vectors", k, "size KB", os.path.getsize(os.path.join(TST, "vectors.h")) // 1024)
